import {PageContainer} from '@ant-design/pro-components';
import {useModel} from '@umijs/max';
import {Card, theme, Row, Col, Statistic, Button, Avatar, Tag, List, Space, Spin, Tooltip, Progress, Timeline} from 'antd';
import {
  BarChartOutlined,
  CloudUploadOutlined,
  HistoryOutlined,
  MessageOutlined,
  UserOutlined,
  DatabaseOutlined,
  SafetyOutlined,
  RocketOutlined,
  ArrowRightOutlined,
  StarOutlined,
  ReloadOutlined,
  BellOutlined,
  ClockCircleOutlined,
  CheckCircleOutlined,
  ExclamationCircleOutlined,
  ThunderboltOutlined,
  FallOutlined,
  RiseOutlined,
  WalletOutlined,
} from '@ant-design/icons';
import React, {useEffect, useState} from 'react';
import {history} from '@umijs/max';
import {listMyChartVOByPageUsingPOST} from '@/services/yubi/chartController';
import moment from 'moment';

/**
 * 每个单独的卡片，为了复用样式抽成了组件
 * @param param0
 * @returns
 */
const InfoCard: React.FC<{
  title: string;
  index: number;
  desc: string;
  href: string;
}> = ({title, href, index, desc}) => {
  const {useToken} = theme;
  const {token} = useToken();

  return (
    <div
      style={{
        backgroundColor: token.colorBgContainer,
        boxShadow: token.boxShadow,
        borderRadius: '8px',
        fontSize: '14px',
        color: token.colorTextSecondary,
        lineHeight: '22px',
        padding: '16px 19px',
        minWidth: '220px',
        flex: 1,
      }}
    >
      <div
        style={{
          display: 'flex',
          gap: '4px',
          alignItems: 'center',
        }}
      >
        <div
          style={{
            width: 48,
            height: 48,
            lineHeight: '22px',
            backgroundSize: '100%',
            textAlign: 'center',
            padding: '8px 16px 16px 12px',
            color: '#FFF',
            fontWeight: 'bold',
            backgroundImage:
              'url(\'https://gw.alipayobjects.com/zos/bmw-prod/daaf8d50-8e6d-4251-905d-676a24ddfa12.svg\')',
          }}
        >
          {index}
        </div>
        <div
          style={{
            fontSize: '16px',
            color: token.colorText,
            paddingBottom: 8,
          }}
        >
          {title}
        </div>
      </div>
      <div
        style={{
          fontSize: '14px',
          color: token.colorTextSecondary,
          textAlign: 'justify',
          lineHeight: '22px',
          marginBottom: 8,
        }}
      >
        {desc}
      </div>
      <a href={href} target="_blank" rel="noreferrer">
        了解更多 {'>'}
      </a>
    </div>
  );
};

const Welcome: React.FC = () => {
  const {token} = theme.useToken();
  const {initialState} = useModel('@@initialState');
  const {currentUser} = initialState || {};
  const [chartStats, setChartStats] = useState({total: 0, success: 0, failed: 0});
  const [recentCharts, setRecentCharts] = useState<API.Chart[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    loadChartStats();
  }, []);

  const loadChartStats = async () => {
    setLoading(true);
    try {
      const res = await listMyChartVOByPageUsingPOST({
        current: 1,
        pageSize: 20,
      });
      if (res.code === 0 && res.data) {
        const records = res.data.records || [];
        const total = res.data.total || 0;
        const pageSuccess = records.filter(r => r.execMessage === '成功').length;
        const pageFailed = records.filter(r => r.execMessage === '失败').length;

        setChartStats({
          total: total,
