    if (submitting) return;
    setSubmitting(true);

    const params = {
      ...values,
      file: undefined,
    };

    try {
      const res = await ByAiAsyncMQUsingPOST(params, {}, values.file.file.originFileObj);
      if (!res?.data) {
        message.error('提交失败');
      } else {
        message.success('分析任务已加入队列，正在处理中...');
        setChartId(res.data.chartId ?? null);
        setChartData(null);
        setChartOption(null);
        form.resetFields();
      }
    } catch (e: any) {
      message.error('提交失败，' + e.message);
    }
    setSubmitting(false);
