  const handleRetry = async () => {
    if (!chartId) return;

    try {
      const res = await reloadChartByAiUsingGET({ chartId });
      if (res?.data) {
        message.success('重试请求已提交');
        setChartData({ ...chartData!, status: 0, execMessage: '等待中' });
        setChartOption(null);
      }
    } catch (e: any) {
      message.error('重试失败，' + e.message);
    }
  };

  const StatusIcon = chartData ? statusConfig[chartData.status as keyof typeof statusConfig]?.icon : ClockCircleOutlined;
  const statusColor = chartData ? statusConfig[chartData.status]?.color : 'orange';
  const statusText = chartData ? statusConfig[chartData.status]?.text : '等待中';

  const currentStep = chartId
    ? chartData?.status === 1 ? 2 : chartData?.status === -1 ? 3 : 1
    : 0;

  return (
    <div className="add-chart-mq">
      <div style={{
        background: 'linear-gradient(135deg, #f093fb 0%, #f5576c 100%)',
        borderRadius: 12,
        padding: '24px 32px',
        marginBottom: 24,
        color: '#fff',
        display: 'flex',
        alignItems: 'center',
        gap: 16,
        boxShadow: '0 4px 20px rgba(245, 87, 108, 0.3)'
      }}>
        <SendOutlined style={{fontSize: 36}} />
        <div>
          <h2 style={{margin: 0, color: '#fff', fontSize: 20}}>异步智能分析（MQ消息队列）</h2>
          <p style={{margin: '8px 0 0 0', opacity: 0.9, fontSize: 14}}>任务进入消息队列，高并发处理保障系统稳定</p>
        </div>
        <Tag color="gold" style={{marginLeft: 'auto', fontSize: 14, padding: '4px 12px'}}>
          <SendOutlined /> MQ队列
        </Tag>
      </div>

      <Steps current={currentStep} size="small" style={{marginBottom: 24}} items={[
        {title: '提交队列', icon: <CloudUploadOutlined />},
        {title: '队列处理', icon: <LoadingOutlined spin />},
        {title: '完成', icon: <CheckCircleOutlined />}
      ]} />

      <Row gutter={24}>
        <Col xs={24} lg={12}>
          <Card
            title={<><AimOutlined style={{color: '#f5576c', marginRight: 8}} />智能分析</>}
            style={{borderRadius: 12, boxShadow: '0 2px 12px rgba(0,0,0,0.08)'}}
            headStyle={{borderBottom: '1px solid #f0f0f0', fontWeight: 600}}
          >
            <Form
              form={form}
              name="addChart"
              labelAlign="left"
              labelCol={{ span: 5 }}
              wrapperCol={{ span: 19 }}
              onFinish={onFinish}
              initialValues={{}}
              hideRequiredMark
            >
              <Form.Item
                name="goal"
                label={<span style={{display: 'flex', alignItems: 'center', gap: 6}}>
                  <span style={{width: 20, height: 20, background: 'linear-gradient(135deg, #f093fb 0%, #f5576c 100%)', borderRadius: 6, display: 'flex', alignItems: 'center', justifyContent: 'center'}}>
                    <AimOutlined style={{fontSize: 12, color: '#fff'}} />
                  </span>
                  分析目标
                </span>}
                rules={[{ required: true, message: '请输入分析目标' }]}
              >
                <TextArea 
                  placeholder="请输入你的分析需求，比如：分析网站用户的增长情况" 
                  rows={4}
                  style={{
                    borderRadius: 8,
                    borderColor: '#e8e8e8',
                    transition: 'all 0.3s ease',
                    resize: 'none'
                  }}
                />
              </Form.Item>
              <Form.Item name="name" label={<span style={{display: 'flex', alignItems: 'center', gap: 6}}>
                  <span style={{width: 20, height: 20, background: 'linear-gradient(135deg, #f093fb 0%, #f5576c 100%)', borderRadius: 6, display: 'flex', alignItems: 'center', justifyContent: 'center'}}>
                    <FileTextOutlined style={{fontSize: 12, color: '#fff'}} />
                  </span>
                  图表名称
                </span>}>
                <Input 
                  placeholder="请输入图表名称（可选）"
                  style={{
                    borderRadius: 8,
                    borderColor: '#e8e8e8',
                    transition: 'all 0.3s ease'
                  }}
                />
              </Form.Item>
              <Form.Item name="chartType" label={<span style={{display: 'flex', alignItems: 'center', gap: 6}}>
                  <span style={{width: 20, height: 20, background: 'linear-gradient(135deg, #f093fb 0%, #f5576c 100%)', borderRadius: 6, display: 'flex', alignItems: 'center', justifyContent: 'center'}}>
                    <BarChartOutlined style={{fontSize: 12, color: '#fff'}} />
                  </span>
                  图表类型
                </span>}>
                <Select
                  placeholder="选择图表类型（可选）"
                  style={{
                    borderRadius: 8,
                    borderColor: '#e8e8e8',
                    transition: 'all 0.3s ease'
                  }}
                  options={[
                    { value: '折线图', label: '折线图' },
                    { value: '柱状图', label: '柱状图' },
                    { value: '堆叠图', label: '堆叠图' },
                    { value: '饼图', label: '饼图' },
                    { value: '雷达图', label: '雷达图' },
                    { value: '热力图', label: '热力图' },
                    { value: '漏斗图', label: '漏斗图' },
                    { value: '散点图', label: '散点图' },
                    { value: '仪表盘', label: '仪表盘' },
                    { value: 'K线图', label: 'K线图' },
                    { value: '长图表', label: '长图表' },
                    { value: '区域图', label: '区域图' },
                    { value: '面积热力图', label: '面积热力图' },
                    { value: '三维散点图', label: '三维散点图' },
                  ]}
                />
              </Form.Item>
              <Form.Item name="file" label={<span style={{display: 'flex', alignItems: 'center', gap: 6}}>
                  <span style={{width: 20, height: 20, background: 'linear-gradient(135deg, #f093fb 0%, #f5576c 100%)', borderRadius: 6, display: 'flex', alignItems: 'center', justifyContent: 'center'}}>
                    <UploadOutlined style={{fontSize: 12, color: '#fff'}} />
                  </span>
                  原始数据
                </span>}>
                <Upload name="file" maxCount={5} accept=".csv,.xlsx,.xls,.txt,.dat,.json,.ods,.parquet,.db" multiple>
                  <div style={{
                    border: '2px dashed #d9d9d9',
                    borderRadius: 8,
                    padding: '24px',
                    textAlign: 'center',
                    transition: 'all 0.3s ease',
                    cursor: 'pointer'
                  }}>
                    <div style={{marginBottom: 8}}>
                      <UploadOutlined style={{fontSize: 32, color: '#999'}} />
                    </div>
                    <p style={{color: '#666', margin: 0}}>点击或拖拽上传数据文件（支持多选）</p>
                    <p style={{color: '#999', fontSize: 12, margin: '8px 0 0 0'}}>支持 CSV、Excel (.xlsx/.xls)、TXT、DAT、JSON、ODS、Parquet、SQLite 格式，单次最多上传 5 个文件，单个最大 10MB</p>
                  </div>
