                    重新分析
                  </Button>
                )}
              </div>
            ) : (
              <div style={{textAlign: 'center', padding: '40px 0', color: '#999'}}>
                <SendOutlined style={{fontSize: 48, marginBottom: 16, opacity: 0.3}} />
                <p>请在左侧提交分析任务</p>
              </div>
            )}
          </Card>

          {chartData?.status === 1 && (
            <>
              <Card
                title={<><FileTextOutlined style={{color: '#f5576c', marginRight: 8}} />分析结论</>}
                style={{borderRadius: 12, boxShadow: '0 2px 12px rgba(0,0,0,0.08)', marginBottom: 16}}
                headStyle={{borderBottom: '1px solid #f0f0f0', fontWeight: 600}}
              >
                <div style={{lineHeight: 1.8}}>{chartData.genResult || '暂无分析结果'}</div>
              </Card>
              <Card
                title={<><BarChartOutlined style={{color: '#f5576c', marginRight: 8}} />可视化图表</>}
                style={{borderRadius: 12, boxShadow: '0 2px 12px rgba(0,0,0,0.08)'}}
                headStyle={{borderBottom: '1px solid #f0f0f0', fontWeight: 600}}
              >
                {chartOption ? (
                  <ReactECharts option={chartOption} style={{ height: 350 }} />
                ) : (
                  <div style={{textAlign: 'center', padding: '40px 0', color: '#999'}}>
                    <p>图表加载失败</p>
                  </div>
                )}
              </Card>
            </>
          )}
        </Col>
      </Row>

      <Modal
        title="积分不足"
        visible={showNoCreditModal}
        onCancel={() => setShowNoCreditModal(false)}
        footer={null}
        closable={true}
      >
        <p>您的积分不足，无法完成此操作。</p>
        <p>请前往积分充值页面进行充值。</p>
        <Button type="primary" onClick={handleGoToRecharge} style={{ marginTop: 16 }}>
          立即充值
        </Button>
      </Modal>
    </div>
  );
};

export default AddChartAsync;

