import {CHART_TYPE} from '@/constants/chart/chartType';
import {
  listMyChartVOByPageUsingPOST,
  reloadChartByAiUsingGET,
  deleteChartUsingPOST
} from '@/services/yubi/chartController';
import ProList from '@ant-design/pro-list';
import {ProListMetas} from '@ant-design/pro-list/lib';
import {ActionType} from '@ant-design/pro-table';
import {useInterval} from 'ahooks';
import {
  Button,
  Collapse,
  message,
  Modal,
  Result,
  Tag,
  Popconfirm,
} from 'antd';
import {DeleteOutlined, DownloadOutlined, EyeOutlined} from '@ant-design/icons';
import {useNavigate} from 'umi';
import ReactECharts from 'echarts-for-react';
import * as echarts from 'echarts';
import React, {useEffect, useRef, useState, useCallback} from 'react';
import {optimizeChartOption} from '@/utils/chartOptimizer';

const TestMyChartPage: React.FC = () => {
  const navigate = useNavigate();
  const initSearchParams = {
    name: '',
    chartType: '',
    current: 1,
    pageSize: 4,
    sortField: 'createTime',
    sortOrder: 'desc',
  };

  const [searchParams, setSearchParams] = useState<API.ChartQueryRequest>({...initSearchParams});
  const [chartList, setChartList] = useState<API.Chart[]>();
  const [total, setTotal] = useState<number>(0);
  const [loading, setLoading] = useState<boolean>(false);
  const [chartId, setChartId] = useState<number>(0);
  const actionRef = useRef<ActionType>();
  const chartRefs = useRef<{ [key: number]: ReactECharts }>({});

  /**
   * 安全解析 JSON 并优化图表配置
   */
  const safeParseJSON = (jsonString: string | undefined, chartName?: string) => {
    if (!jsonString) return {};
    try {
      const parsed = JSON.parse(jsonString);
      const optimized = optimizeChartOption(parsed);
      if (chartName && optimized) {
        optimized.title = {
          text: chartName,
          left: 'center',
          top: 10,
          textStyle: {
            fontSize: 14,
            fontWeight: 'bold',
            color: '#333',
          },
        };
        if (optimized.grid) {
          optimized.grid.top = optimized.grid.top > 60 ? optimized.grid.top : 70;
        } else {
          optimized.grid = { top: 70 };
        }
      }
      return optimized;
    } catch (error) {
      console.error('JSON 解析失败:', error);
      return {};
    }
  };

  /**
   * 加载数据
   */
  const loadData = async () => {
    setLoading(true);
    try {
      const res = await listMyChartVOByPageUsingPOST(searchParams);
      const data = res?.data;
      if (res.code === 0 && data) {
        // message.success('加载成功');
        setChartList(data?.records ?? []);
        setTotal(data.total ?? 0);
      } else {
        message.error('获取图表列表失败');
      }
    } catch (e: any) {
      message.error('获取图表列表失败', e.message);
    }
    setLoading(false);
  };

  /**
   * 手动重新生成图表
   * @param params
   */
  const reloadChart = async (params: number) => {
    if (params === undefined) {
      message.error('id为空');
      return;
    }
    const data = {
      chartId: params,
    };
    try {
      const res = await reloadChartByAiUsingGET(data);
      if (res.code === 0 && data) {
        message.success('请求成功，图表生成中请稍后');
      } else {
        message.error('重新生成图表失败');
      }
    } catch (e: any) {
      message.error('重新生成图表失败', e.message);
    }
  };

  /**
   * 删除图表
   * @param chartId
   */
  const deleteChart = async (chartId: number) => {
    if (chartId === undefined) {
      message.error('id为空');
      return;
    }
    const data = {
      id: chartId,
    };
    try {
      const res = await deleteChartUsingPOST(data);
      if (res.code === 0) {
        message.success('删除成功');
        loadData();
      } else {
        message.error('删除失败');
      }
    } catch (e: any) {
      message.error('删除失败', e.message);
    }
  };

  /**
   * 导出图表为PNG图片
   * @param chartId 图表ID
   * @param chartName 图表名称
   */
  const exportChart = useCallback((chartId: number, chartName: string) => {
    const chartRef = chartRefs.current[chartId];
    if (!chartRef) {
      message.error('图表实例未找到');
      return;
    }

    try {
      // 获取ECharts实例
      const echartsInstance = chartRef.getEchartsInstance();
      if (!echartsInstance) {
        message.error('无法获取图表实例');
        return;
      }

      // 获取图片数据URL
      const url = echartsInstance.getDataURL({
        type: 'png',
        pixelRatio: 2,
        backgroundColor: '#fff',
      });

      // 创建下载链接
      const link = document.createElement('a');
      link.download = `${chartName || 'chart'}_${Date.now()}.png`;
      link.href = url;
      link.click();

      message.success('图表导出成功');
    } catch (e: any) {
      message.error('图表导出失败: ' + e.message);
    }
  }, []);

  useEffect(() => {
    loadData();
  }, [searchParams]);

  //每30s加载一次数据
  useInterval(() => {
    loadData();
  }, 30000);

  /**
   * 处理图表类型
   */
  const handleType = () => {
    return CHART_TYPE.reduce((obj: any, item) => {
      obj[item.value] = item.label;
      return obj;
    }, {});
  };

  /**
   * 列表元素
   */
  const metas: ProListMetas<API.Chart> = {
    id: {
      title: 'id',
      dataIndex: 'id',
      valueType: 'index',
      search: false,
    },
    title: {
      title: '图表名称',
      dataIndex: 'name',
    },
    subTitle: {
      title: '图表类型',
      dataIndex: 'chartType',
      valueEnum: handleType(),
      render: (_, item) => {
        return <Tag color="#5BD8A6">{'图表类型：' + item.chartType}</Tag>;
      },
    },
    content: {
      search: false,
      render: (_, item) => {
        return (
          <div style={{flex: 1}}>
            <div>
              <p>{item.goal}</p>
            </div>
            {item.execMessage === "等待中" && (
              <div>
                <Result status="warning" title="等待处理" subTitle={item.execMessage}/>
              </div>
            )}
            {item.execMessage === "生成中" && (
              <div>
                <Result status="info" title="图表生成中" subTitle={item.execMessage}/>
              </div>
            )}
            {item.execMessage === "失败" && (
              <div>
                <Result
                  status="error"
                  title="图表生失败"
                  subTitle={item.execMessage}
                  extra={[
                    <Button
                      key="tryAgain"
                      type="primary"
                      danger
                      onClick={() => {
                        reloadChart(item.id as number);
                      }}
                    >
                      请重试
                    </Button>,
                  ]}
                />
              </div>
            )}
            {item.execMessage === "成功" && (
              <div>
                <div style={{width: '100%', height: '300px'}}>
                  <ReactECharts 
                    ref={(ref) => { if (ref) chartRefs.current[item.id as number] = ref; }}
                    option={safeParseJSON(item.genChart, item.name)} 
                    style={{height: '100%'}}
                  />
                </div>
                <div style={{marginTop: 12, textAlign: 'right'}}>
                  <Button
                    type="primary"
                    icon={<EyeOutlined />}
                    onClick={() => navigate(`/chart_detail/${item.id}`)}
                  >
                    查看详情
                  </Button>
                </div>
              </div>
            )}
            <div>
              <Collapse
                bordered={false}
                items={[
                  {
                    key: item.id,
                    label: 'Ai分析结论',
                    children: <p>{item.genResult}</p>,
                  },
                ]}
              />
            </div>
            <div style={{marginTop: 16, textAlign: 'right'}}>
              <Popconfirm
                title="确定要删除这个图表吗？"
                onConfirm={() => deleteChart(item.id as number)}
                okText="确定"
                cancelText="取消"
              >
                <Button
                  type="text"
                  danger
                  icon={<DeleteOutlined />}
                  onClick={(e) => e.stopPropagation()}
                >
                  删除
                </Button>
              </Popconfirm>
            </div>
          </div>
        );
      },
    }
  };

  return (
    <div className="my-chart-page">
      <ProList<API.Chart>
        grid={{gutter: 16, column: 2}}
        ghost={true}
        loading={loading}
        actionRef={actionRef}
        search={{
          labelWidth: 'auto',
          defaultCollapsed: false,
        }}
        request={async (params) => {
          const res = await listMyChartVOByPageUsingPOST({
            ...searchParams,
            name: params.name,
            chartType: params.chartType,
            current: params.current,
            pageSize: params.pageSize,
          });

          if (res.code === 0 && res.data) {
            setChartList(res.data.records ?? []);
            setTotal(res.data.total ?? 0);
            return {
              data: res.data.records ?? [],
              success: true,
              total: res.data.total ?? 0,
            };
          }

          return {
            data: [],
            success: false,
            total: 0,
          };
        }}
        rowKey="id"
        pagination={{
          onChange: (page, pageSize) => {
            // console.log(page, pageSize);
            setSearchParams({
              ...searchParams,
              name: '',
              chartType: '',
              current: page,
              pageSize,
            });
          },
          current: searchParams?.current,
          pageSize: searchParams?.pageSize,
          total: total,
        }}
        dataSource={chartList}
        metas={metas}
      />
    </div>
  );
};
export default TestMyChartPage;

