            </Row>
            <Table
              columns={systemColumns}
              dataSource={systemData}
              pagination={false}
              size="small"
              style={{ marginTop: 16 }}
            />
          </Card>
        </Col>
      </Row>
    </PageContainer>
  );
};

export default Monitor;

